"""Read-only summaries of obs and must JSONL sequences."""
import argparse
from collections import Counter
import json
from pathlib import Path
import re
import stat

CHANNELS = ("obs", "must")
NUMBERED = re.compile(r"(obs|must)\.([0-9]{12})\.jsonl\Z")


def reject_constant(value):
    raise ValueError("non-JSON constant")


def decode(raw):
    return json.loads(raw.decode("utf-8"), parse_constant=reject_constant)


def integer(value):
    return type(value) is int


def read_state(folder, bad):
    fields = {ch: None for ch in CHANNELS}
    path = folder / "state.json"
    if not path.exists() and not path.is_symlink():
        return fields
    try:
        data = decode(path.read_bytes())
    except (OSError, ValueError, UnicodeError):
        data = None
    if (not isinstance(data, dict)
            or not isinstance(data.get("channels"), dict)
            or any(not isinstance(data["channels"].get(ch), dict)
                   for ch in CHANNELS)):
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return fields
    invalid = False
    for ch in CHANNELS:
        item = data["channels"][ch]
        next_seq = item.get("next_seq")
        acked = item.get("acked_upto")
        if not integer(next_seq) or (ch == "must" and not integer(acked)):
            invalid = True
        else:
            fields[ch] = (next_seq, acked)
    if invalid:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    return fields


def channel_files(folder):
    files = {ch: [] for ch in CHANNELS}
    for path in folder.iterdir():
        name = path.name
        match = NUMBERED.fullmatch(name)
        if match:
            ch = match.group(1)
            order = (0, int(match.group(2)))
        elif name in ("obs.active.jsonl", "must.active.jsonl"):
            ch = name.split(".", 1)[0]
            order = (1, 0)
        else:
            continue
        if stat.S_ISREG(path.lstat().st_mode):
            files[ch].append((order, path))
    return {ch: [path for _, path in sorted(files[ch])] for ch in CHANNELS}


def read_channel(paths, bad):
    counts = Counter()
    for path in paths:
        parts = path.read_bytes().split(b"\n")
        for line_no, raw in enumerate(parts[:-1], 1):
            try:
                record = decode(raw)
            except (ValueError, UnicodeError):
                why = "bad_json"
            else:
                if not isinstance(record, dict) or not integer(record.get("seq")) or record["seq"] < 1:
                    why = "no_seq"
                else:
                    counts[record["seq"]] += 1
                    continue
            bad.append({"file": path.name, "line": line_no, "why": why})
        if parts[-1]:
            bad.append({"file": path.name, "line": len(parts), "why": "torn"})
    seqs = sorted(counts)
    return counts, seqs


def summarize(folder):
    bad = []
    state = read_state(folder, bad)
    files = channel_files(folder)
    channels = {}
    for ch in CHANNELS:
        counts, seqs = read_channel(files[ch], bad)
        last = seqs[-1] if seqs else None
        fields = state[ch]
        next_seq = fields[0] if fields else None
        channels[ch] = {
            "count": sum(counts.values()),
            "first": seqs[0] if seqs else None,
            "last": last,
            "missing": [[a + 1, b - 1] for a, b in zip(seqs, seqs[1:]) if b > a + 1],
            "dup": [seq for seq in seqs if counts[seq] >= 2],
            "next_seq": next_seq,
            "unacked": (sum(seq > fields[1] for seq in seqs)
                        if ch == "must" and fields else None),
            "stale_next": (next_seq != last + 1 if fields and last is not None else None),
        }
    bad.sort(key=lambda item: (item["file"], item["line"] or 0, item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only node sequence summary")
    parser.add_argument("folder", type=Path)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder), separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
